<script lang="ts">
 import {onMount} from 'svelte';import {GitBranch,RefreshCw,Hammer,ArrowLeft,BookOpen,Check} from '@lucide/svelte';import Guard from '$lib/Guard.svelte';import Notice from '$lib/Notice.svelte';import {api,session,refresh} from '$lib/api';import type {AdminView,Template} from '$lib/types';let data=$state<AdminView|null>(null);let error=$state('');let busy=$state(false);let selected=$state<Template|null>(null);let confirmation:HTMLDialogElement;
 async function load(){try{await refresh();if($session?.user.admin)data=await api<AdminView>('/api/admin')}catch(e){error=(e as Error).message}}
 onMount(()=>{void load();const t=setInterval(load,5000);return()=>clearInterval(t)});
 async function run(path:string,body:unknown={}){busy=true;error='';try{await api(path,body);confirmation?.close();await load()}catch(e){error=(e as Error).message}finally{busy=false}}
</script>
<svelte:head><title>Lab templates · LabCentral</title></svelte:head>
<a href="/admin/" class="link mb-7 inline-flex items-center gap-2 text-sm"><ArrowLeft size={16}/>Manage meeting</a><div class="flex flex-wrap items-start justify-between gap-5"><div><h1 class="text-3xl font-semibold tracking-tight sm:text-4xl">Lab templates</h1><p class="mt-3 max-w-xl leading-relaxed text-base-content/70">Shared source from example/lab-templates. Each revision stays pinned to the commit you import.</p></div>{#if $session?.user.admin}<button disabled={busy} onclick={()=>run('/api/admin/templates/refresh')} class="btn btn-sm btn-primary"><RefreshCw size={16}/>Refresh from GitHub</button>{/if}</div>
<Guard admin><Notice message={error}/>{#if data}<ul class="mt-10 divide-y divide-base-300 border-y border-base-300">{#each data.templates as template}<li class="flex flex-wrap items-start gap-5 py-7"><BookOpen size={24} class="mt-1"/><div class="min-w-0 flex-1"><h2 class="text-xl font-semibold">{template.name}</h2><p class="mt-3 flex items-center gap-2 text-sm text-base-content/65"><GitBranch size={15}/><code>{template.commit.slice(0,12)}</code></p><p class="mt-3 text-sm text-base-content/70">{template.built?'Images are ready for a new meeting.':'Build reusable images before starting a meeting.'}</p></div>{#if template.built}<span class="badge badge-sm"><Check size={13}/>Built</span>{:else}<button disabled={busy||data.jobs.some(j=>j.target===template.id&&(j.status==='queued'||j.status==='running'))} class="btn btn-sm" onclick={()=>{selected=template;confirmation.showModal()}}><Hammer size={16}/>Build images</button>{/if}</li>{:else}<li class="py-12"><GitBranch size={28}/><h2 class="mt-5 text-xl font-semibold">Import the first lab</h2><p class="mt-3 max-w-lg leading-relaxed text-base-content/70">Refresh from GitHub to discover the current Example Branch source. Importing does not start any lab machines.</p></li>{/each}</ul><p class="mt-6 text-sm text-base-content/70">Build progress and recovery actions appear in <a class="link" href="/admin/">meeting operations</a>. Importing a revision never changes a running lab.</p>{/if}</Guard>
<dialog bind:this={confirmation} class="modal" aria-labelledby="build-title"><div class="modal-box"><h2 id="build-title" class="text-xl font-semibold">Build {selected?.name}?</h2><p class="mt-4 leading-relaxed">This provisions temporary build and validation machines for four reusable images. Builds may take up to two hours; charges apply while those machines run. Existing matching images are reused.</p><Notice message={error}/><div class="modal-action"><form method="dialog"><button class="btn btn-sm">Cancel</button></form><button class="btn btn-sm btn-primary" disabled={busy} onclick={()=>run('/api/admin/templates/build',{id:selected?.id})}>Build images</button></div></div></dialog>
